    seen=np.zeros_like(g,bool); best=None
    while True:
        p=np.argwhere(g==color&~seen)
        if not len(p): break
        s=set(p.tolist()); stack=p
        while stack:
            y,x=stack.pop(); 
            for dy in(-1,0,1):
